-- db/seeds/reconciliation/04_registry.sql
-- F1 — seeds sys.sys_reconciliation_registry with the F0-verified, sign-off classification
-- of all 65 empty sys.* tables. Generated from the F0 workflow JSON (run wf_10873576-5a0)
-- + 5 sign-off borderline overrides (bonus_pools->A, inbox_notifications->D, auth_sessions src strip).
-- Buckets: A:5 B:16 C:23 D:21 = 65.
-- IDEMPOTENT: ON CONFLICT (table_name) DO UPDATE. 2nd run updates in place (no duplicate rows).

BEGIN;

INSERT INTO sys.sys_reconciliation_registry (
  reconciliation_registry_table_name, reconciliation_registry_bucket,
  reconciliation_registry_declared_status, reconciliation_registry_legacy_source,
  reconciliation_registry_legacy_source_rows, reconciliation_registry_wall,
  reconciliation_registry_rationale
) VALUES
  ('sys_process_kpi_templates', 'B', 'NEEDS_DECISION', 'process_kpis', 81, 'other:legacy business_processes keyspace (BP-001..BP-SF-007) does not map to blueprint_process_registry ordinals (00..22)', '[VERIFIED] Legacy source WITH rows exists (process_kpis=81 exact) and the kpi FK resolves 1:1 by code (81/81 confirmed by comm with C-locale, contradicting the stage-1 implication that codes might diverge). But the NOT-NULL process FK to sys_blueprint_process_registry cannot resolve: legacy process keyspace (business_processes.process_code BP-xxx) is a different model from the blueprint registry ordinal codes (00..22). Required FK unresolvable without a modeling bridge -> structural wall -> B (not A). brownfield.table_mappings says IMPORT but that is contradicted by the failed process FK closure.'),
  ('sys_organization_unit_kpi_templates', 'B', 'NEEDS_DECISION', 'org_unit_kpis', 100, 'org_unit_template_vs_instance', '[VERIFIED] Bucket unchanged (B) but stage-1 rationale partly WRONG: the claimed kpi-code keyspace divergence (''KPI-0001'' vs sys) is false — re-verification shows 100/100 org_unit_kpis codes exist in sys_kpi_definitions (sys has KPI-0001..KPI-0085 and KPI-001..KPI-015). The genuine wall is template-vs-instance: org_unit_kpis is keyed at the org_unit TEMPLATE level (org_unit_template_id->org_unit_templates, 225 rows) while the target requires a real org-unit INSTANCE (sys_organization_units, 26 rows) — the canonical org_unit_template_vs_instance wall. Required unit FK needs a modeling decision -> B.'),
  ('sys_position_kpi_requirements', 'B', 'NEEDS_DECISION', 'tenant_job_kpis', 80, 'job_to_position_bridge', '[VERIFIED] A legacy source WITH rows exists for job-level KPIs (tenant_job_kpis=80 exact, job_kpis=2000 exact) but the target is POSITION-centric and no legacy table keys KPIs to a position instance (confirmed by scanning all public tables matching position/kpi: only position_skill_requirements is position-keyed, and it is skills not KPI). Resolving NOT-NULL position_id requires the job_to_position_bridge. Required FK unresolvable without a bridge -> B.'),
  ('sys_kpi_metric_definitions', 'C', 'NEEDS_DECISION', NULL, NULL, NULL, '[VERIFIED] Derived/authored analytics. The table models sub-metrics of a KPI with aggregation type; no legacy public table provides a 1:1 row source. Legacy KPIs carry a single benchmark, not a metric breakdown, and the four legacy ''*_metrics'' tables are skill/provider/ontology metrics, not KPI metric definitions. Populating requires a human-authored derivation of which metrics compose each KPI -> needs-decision (C). The single FK resolves, so it is not a structural-wall import; it is the absence of any populated 1:1 source.'),
  ('sys_kpi_assessment_results', 'C', 'NEEDS_DECISION', NULL, NULL, NULL, '[VERIFIED] Pure derived analytics (scored assessment results per user|position|period via one of 5 sys methods). No 1:1 legacy source: re-verification of ''*_result/*_score'' legacy tables found none KPI-scoring-shaped; employee_kpi_targets is targets/actuals with a generated achievement ratio, not a scored result tied to sys_kpi_assessment_methods. Computing scores requires a human-authored scoring rule + method mapping -> needs-decision (C).'),
  ('sys_kpi_measurements', 'C', 'NEEDS_DECISION', NULL, NULL, NULL, '[VERIFIED] Derived/aggregation analytics. A generic time-series KPI measurement feed (value numeric(18,4) + source) has no row-for-row legacy source: the legacy %measurement% scan returned nothing, and employee_kpi_targets is a target/actual record per job-KPI, not a measurement stream. Projecting target-actuals into measurements requires a human-authored aggregation/derivation rule -> needs-decision (C). Not B because the gap is the derivation rule itself, not a single source whose FK merely lacks a bridge.'),
  ('sys_user_kpi_evidence', 'C', 'NEEDS_DECISION', NULL, NULL, NULL, '[VERIFIED] Person-centric KPI evidence (measured vs target value per user/period). Under I14/ADR-0024 the correct driver is legacy employees + employee_kpi_targets (employee-centric, FK to employees_core), confirmed NOT legacy users (doctrine-correct in stage-1). However the values are a derived/aggregated achievement snapshot requiring a human-authored rule (which target/actual snapshot, period grain, kpi_code crosswalk) -> needs-decision (C). employee_kpi_targets(412) is the nearest source but is target/actual outcome data, not 1:1 user-period evidence rows; conservative tie-breaker keeps it C over a speculative B.'),
  ('sys_career_paths', 'A', 'IMPORT', 'career_paths', 32, NULL, '[VERIFIED] Re-ran legacy count public.career_paths = 32 (>0). Legacy DDL maps ~1:1: name->career_path_name, description->career_path_description, path_type->career_path_kind (CHECK-mappable), tenant_id->career_path_tenant_id (nullable, FK resolves to the 2 present sys_tenancies). Every NOT-NULL/FK target column resolves from data already in sys.* with no missing bridge -> deterministic import -> A.'),
  ('sys_career_path_steps', 'B', 'NEEDS_DECISION', 'career_path_levels', 75, 'job_to_position_bridge', '[VERIFIED] Re-ran legacy count public.career_path_levels = 75 (>0) and public.tenant_jobs = 20. Source populated -> not C/D. The natural ordered-step structure maps (level_order->ordinal, typical_duration_months->step_typical_duration_months, required_skills->required_proficiency_uplift jsonb). The required step semantics depend on the job->position bridge (legacy is job-keyed via target_job_id, target is position-keyed); that bridge is an unresolved modeling decision -> structural wall, not deterministic A -> B.'),
  ('sys_position_career_paths', 'B', 'NEEDS_DECISION', 'career_path_levels', 75, 'job_to_position_bridge', '[VERIFIED] A populated upstream legacy source exists (career_path_levels 75 rows carry the only job linkage that could seed this junction), so not C/D. But the NOT-NULL position_id cannot be deterministically resolved: legacy links paths to jobs (via levels.target_job_id), never to positions, and the job->position mapping is the unresolved structural decision -> wall job_to_position_bridge -> B.'),
  ('sys_user_career_plans', 'A', 'IMPORT', 'employee_career_paths', 128, NULL, '[VERIFIED] Re-ran legacy count public.employee_career_paths = 128 (>0). EMPLOYEE-CENTRIC doctrine respected: the legacy FK is employee_id -> employees_core (verified in DDL: fk_ecp_employee), NOT users — driver is employees, crosswalk ''LEGACY_EMP::''. Columns map ~1:1: employee_id->user, path_id->user_career_plan_path_id (nullable), status->user_career_plan_status, target_completion/started_at->metadata/horizon. Every NOT-NULL/FK resolves (tenant present, user resolves via 57/66 crosswalk hits, path/target nullable). Source populated + FKs resolve -> A (not B, not C).'),
  ('sys_user_target_positions', 'C', 'NEEDS_DECISION', NULL, NULL, NULL, '[VERIFIED] Aspirational/derived analytics: a user-authored career target plus an approval workflow. Exhaustive inventory grep (position|aspir|target|weight|valuation|grade|evaluation|ranking|importance|criticality) found NO position-keyed aspiration table; only employee_kpi_targets(412, KPI not position), job_evaluations(15, job-level), position_skill_requirements(1632, skill reqs not aspirations). Nearest career_simulations(20) is job/path/level-keyed derived prediction, not a 1:1 (user,position) target, and lacks the review workflow entirely. No positively-found populated 1:1 legacy source -> C (derived analytics, needs human-authored derivation rule). Conservative on doubt.'),
  ('sys_position_economic_weight', 'C', 'NEEDS_DECISION', NULL, NULL, NULL, '[VERIFIED] Derived analytics measurement (computed normalized weight per position over time). Exhaustive inventory grep (weight|economic|valuation|grade|evaluation|importance|criticality) surfaced no per-position weight table; job_evaluations is job-level point-factor scoring (15 rows, keyed to jobs via job_analysis_id/job_title, not positions) requiring a human-authored aggregation/derivation rule to become a per-position numeric weight with periods. No positively-found populated 1:1 source -> C. Conservative on doubt.'),
  ('sys_position_skill_requirements', 'B', 'NEEDS_DECISION', 'position_skill_requirements', 1632, 'job_to_position_bridge', '[VERIFIED] Real populated legacy source position_skill_requirements (1632 rows, columns map ~1:1: position, esco_skill_id/custom_skill_name, minimum_proficiency, weight) -> not C/D. Not A: the position_id NOT-NULL FK references legacy job_templates (the job-vs-position split) with no bridge to the 162 sys_positions (no legacy-id column, ESCO occupation URI 0/162 populated), and the skill side has no deterministic legacy-id->sys_skills key. brownfield.table_mappings classifies all related sources (position_skill_requirements / skill_requirements_templates / job_template_skills / esco_occupation_skills / onet_*) as REFERENCE_ONLY, confirming non-deterministic import. Dominant wall = job_to_position_bridge. Conservative A->B.'),
  ('sys_position_skill_requirement_history', 'D', 'NO_SOURCE', NULL, NULL, NULL, '[VERIFIED] *_history audit/change-log table (verified DDL: old_proficiency/new_proficiency, old_weight/new_weight, change_reason, actor_user_id, effective_at -> classic row-level diff change-log shape). Per the *_history -> D tie-breaker, stays D unless a POPULATED legacy source is positively found: there is NO brownfield.table_mappings row for this target (classification blank, verified) and no legacy row-level proficiency-change audit source exists in the inventory. App-generated change log written on UPDATE of sys_position_skill_requirements (empty). No-source / app-generated.'),
  ('sys_position_learning_requirements', 'B', 'NEEDS_DECISION', 'job_title_courses', 207, 'job_to_position_bridge', '[VERIFIED] The brownfield table_mappings-named source job_title_learning_paths is EMPTY (count=0, verified). The populated semantic equivalent job_title_courses has 207 rows (job_title -> course requirement, requirement_type, priority) -> a populated legacy source WITH rows exists, so not C/D. Not A: the position side cannot resolve (job_title varchar -> 162 sys_positions has no bridge: the job-vs-position split) and the learning side needs a course->sys_learning_path crosswalk that does not exist. Dominant wall = job_to_position_bridge. table_mappings = REFERENCE_ONLY. Conservative A->B.'),
  ('sys_learning_path_steps', 'B', 'NEEDS_DECISION', 'learning_path_courses', 124, 'learning_catalog_reimport', '[VERIFIED] Real populated legacy source learning_path_courses=124 (verified DDL: learning_path_id, course_id, sequence_order, is_mandatory -> ordered path-step semantics); course_modules=564 is the module decomposition side. Source-with-rows -> not C/D. Not A: both NOT-NULL FKs require a legacy-course/path-id -> sys-catalog-id crosswalk that does not exist (the catalog was bulk re-imported, not key-preserving). Wall = learning_catalog_reimport. table_mappings = REFERENCE_ONLY (sources learning_path_courses + course_modules).'),
  ('sys_skill_learning_mappings', 'B', 'NEEDS_DECISION', 'course_esco_skills', 717, 'learning_catalog_reimport', '[VERIFIED] Real populated legacy source course_esco_skills=717 (verified DDL: course_id, esco_skill_uri, skill_name, proficiency_level_gained -> the skill<->learning bridge); supporting certification_esco_skills=664, job_title_courses=207. Source-with-rows -> not C/D. Not A: the module side needs a course->sys_learning_module crosswalk that does not exist (re-imported catalog), and the skill side has only a non-deterministic ESCO-URI match. Wall = learning_catalog_reimport. table_mappings = REFERENCE_ONLY (sources job_title_courses, course_esco_skills, certification_esco_skills).'),
  ('sys_user_learning_assignments', 'B', 'NEEDS_DECISION', 'course_enrollments', 3052, 'learning_catalog_reimport', '[VERIFIED] Real populated legacy source course_enrollments=3052 (verified DDL: employee_id, course_id, status, due_date, is/mandatory via enrollment_source -> assignment semantics). Employee-centric (I14/ADR-0024): the person FK resolves from legacy employees (employee_id -> employees_core), NOT from legacy users -> doctrine satisfied. Source-with-rows -> not C/D. Not A: the mandatory scope target (module/path/initiative) cannot resolve without the learning-catalog crosswalk. Person side fine; wall = learning_catalog_reimport.'),
  ('sys_user_learning_evidence', 'B', 'NEEDS_DECISION', 'course_enrollments', 3052, 'learning_catalog_reimport', '[VERIFIED] Real populated completion-evidence sources: course_enrollments=3052 (verified DDL has completed_at, score, passed, certificate_url, certificate_issued) + employee_training_records=320 (completion_date, score, certificate_url). Employee-centric (I14): person FK resolves from legacy employees not users -> doctrine satisfied. Source-with-rows -> not C/D. Not A: the NOT-NULL module_id requires the course->sys_learning_module crosswalk that does not exist. Wall = learning_catalog_reimport.'),
  ('sys_learning_gaps', 'C', 'NEEDS_DECISION', NULL, NULL, NULL, '[VERIFIED] Derived analytics (verified DDL: learning_gap_required_proficiency vs learning_gap_current_proficiency, learning_gap_score, learning_gap_severity -> computed comparison; feeds sys_gap_closure_actions). The closest legacy artifacts are analytics blobs, NOT 1:1 per-gap sources: skill_gap_analyses=304 stores skill_gaps/skill_matches/recommendations as JSONB per-analysis (verified DDL, analysis-level not row-per-gap, also carries analysis_embedding vector(1536)) and skill_development_paths=65 stores missing_skills as text[]. No deterministic 1:1 legacy table maps to per-(user,skill) gap rows; populating requires a human-authored derivation/aggregation rule (compare position skill requirements vs user proficiency). The ''real source -> never C'' tie-breaker does NOT apply because no source maps ~1:1 — the candidates are themselves derived analytics blobs. No brownfield.table_mappings IMPORT/REFERENCE entry for this target (verified blank). Canonical derived-gaps case -> C.'),
  ('sys_succession_pools', 'B', 'NEEDS_DECISION', 'public.talent_pools (primary, 24) + public.succession_plans (31) / public.critical_roles (16)', 24, 'job_to_position_bridge', '[CORRECTED B->B (source enriched, bucket unchanged): the proposal missed public.talent_pools (24 rows) + talent_pool_members (40) which are the cleanest pool-entity source — better than succession_plans/critical_roles for name/description/status. Re-verified: talent_pools=24 (all active). But ALL three candidate sources lack a resolvable position link, and the NOT-NULL succession_pool_position_id -> sys_positions requires a job/role-name->position-UUID modeling decision that does not exist in legacy data. Source WITH rows -> never C/D; required FK needs a modeling decision -> B. Bucket B stands, wall job_to_position_bridge.]'),
  ('sys_successor_candidates', 'B', 'NEEDS_DECISION', 'public.succession_candidates (206) + public.talent_pool_members (40)', 206, 'job_to_position_bridge', '[CORRECTED B->B (source enriched, bucket unchanged): proposal omitted public.talent_pool_members (40 rows, employee_id 40/40) which is the natural pool<->member source. Re-verified both. Person FK confirmed resolvable via legacy EMPLOYEES (candidate_employee_id, doctrine respected — NOT users; this is correct per I14). But the mandatory successor_candidate_pool_id inherits the unresolved position bridge from sys_succession_pools. Source WITH rows + person FK resolves, but a required FK needs a modeling decision first -> conservative B.]'),
  ('sys_successor_readiness', 'C', 'NEEDS_DECISION', NULL, NULL, NULL, '[VERIFIED] Derived-analytics table: a numeric readiness SCORE + horizon snapshot per candidate, assessed_at timestamped. Searched inventory and semantics — legacy succession_candidates carries only a categorical readiness_level (CHECK enum ready_2_years etc.) which already lands in sys_successor_candidates.successor_candidate_readiness_level, NOT a numeric score here. No legacy numeric readiness score table exists. Populating requires a human-authored scoring/derivation rule -> C. Conservative tie-breaker: no 1:1 source with count>0 -> stays C.'),
  ('sys_succession_scores', 'C', 'NEEDS_DECISION', NULL, NULL, NULL, '[VERIFIED] Derived analytics: a computed succession-fitness SCORE per user x position x horizon (succession_score_computed_at). Searched inventory — no legacy table holds such a numeric score; only categorical readiness in succession_candidates and the derived mv_talent_signals (a materialized view, not a base source). Must be derived by an aggregation/scoring rule (human-authored). Even if a position bridge would also be needed, the table is fundamentally derived-analytics with no 1:1 source -> C.'),
  ('sys_talent_scores', 'C', 'NEEDS_DECISION', NULL, NULL, NULL, '[VERIFIED] 9-box talent analytics (potential x performance band). Re-inspected the closest legacy artifact mv_talent_signals (270 rows): it is a derived MATERIALIZED VIEW exposing review_avg_12m, mood/stress avgs, attrition_risk_score int, is_high_potential BOOLEAN — NOT a 1:1 source for potential/performance numeric(5,2) scores or the categorical band. Producing talent_score_potential/performance/band needs a human-authored derivation rule (the boolean is_high_potential is not the numeric pair). No 1:1 base source -> C.'),
  ('sys_readiness_scores', 'C', 'NEEDS_DECISION', NULL, NULL, NULL, '[VERIFIED] Derived analytics: numeric readiness SCORE per user x position x horizon (computed_at). Legacy only has categorical readiness_level on succession_candidates (which lands in sys_successor_candidates, not as a numeric value here). The numeric readiness_score_value requires a human-authored scoring/derivation rule. Distinct from sys_successor_candidates (categorical, B) — this is the numeric-score variant -> C.'),
  ('sys_critical_positions', 'B', 'NEEDS_DECISION', 'public.critical_roles (16) + public.succession_plans (31)', 16, 'job_to_position_bridge', '[VERIFIED] Real legacy source WITH rows (critical_roles=16: criticality_level, impact_if_vacant, succession_status; succession_plans criticality_level) maps semantically to critical_position_rationale/business_impact_score. But the mandatory critical_position_position_id (also UNIQUE) requires resolving a role/job name to a v5 sys_positions UUID — a modeling/bridge decision, not deterministic. Source WITH rows -> not C/D; FK needs decision -> B.'),
  ('sys_critical_role_coverage_status', 'C', 'NEEDS_DECISION', NULL, NULL, NULL, '[VERIFIED] Derived analytics: an aggregation/rollup of successor readiness per critical position (counts by horizon + overall coverage score). Although legacy critical_roles carries a single categorical succession_status (no_successor/successor_ready/at_risk/etc.), the target stores computed per-horizon COUNTS and a numeric coverage score that must be aggregated from candidate readiness via a human-authored rule. No 1:1 legacy source for the counts -> C.'),
  ('sys_position_succession_relevance', 'B', 'NEEDS_DECISION', 'public.critical_roles (16) + public.succession_plans (31)', 16, 'job_to_position_bridge', '[VERIFIED] A legacy source WITH rows exists carrying the is_critical / readiness_horizon semantics (critical_roles.criticality_level + succession_status, succession_plans.criticality_level + risk_level). But this table is keyed on a UNIQUE NOT-NULL position_id and that FK requires resolving job/role names to v5 position UUIDs — a modeling decision (job_to_position_bridge). Source WITH rows -> not C/D; required FK unresolved -> B.'),
  ('sys_employee_position_fit_scores', 'C', 'NEEDS_DECISION', NULL, NULL, NULL, '[VERIFIED] Derived analytics: a per-dimension FIT SCORE of an employee against a position. No legacy table stores such computed fit scores; the inventory holds raw position_skill_requirements (1632) as requirements but no employee-position fit score table. Must be computed from skills/KPI/learning data via a human-authored multi-dimension scoring rule. No 1:1 legacy source -> C (regardless of the additional position-bridge need; derived-analytics nature dominates).'),
  ('sys_gap_analysis_results', 'A', 'IMPORT', 'public.skill_gap_analyses', 304, NULL, '[VERIFIED] Derived analytics table (overall_score, kind, payload jsonb of computed gap results). Real legacy source WITH rows positively confirmed: skill_gap_analyses count(*)=304 re-run, a derived-analytics table with near-1:1 columns (overall_match_score->overall_score, skill_gaps/recommendations/priority_skills jsonb->payload, analysis_type maps to kind, all SKILL-domain). Tie-breaker: real source WITH rows -> never C/D. The mandatory person FK resolves via the correct employee-centric crosswalk (all 304 rows reference an employee target that resolves to employees), and tenant/position FKs resolve from populated sys.* tables; the FK mechanism resolves without any modeling decision (just match-or-skip), so A over B (B requires a FK that CANNOT resolve without a decision). Confidence medium: column mapping is not strictly 1:1 (legacy is SKILL-only while target kind is multi-kind SKILL/KPI/LEARNING/CERTIFICATION/BEHAVIORAL/COMPOSITE) and per-row person-FK coverage is partial (146/180 distinct subjects, 81%).'),
  ('sys_gap_closure_plans', 'C', 'NEEDS_DECISION', NULL, NULL, NULL, '[VERIFIED] Derived planning output (milestones jsonb, status PROPOSED/ACTIVE/COMPLETED/CANCELLED/ON_HOLD, owner_user_id, target_completion_date) representing remediation/development plans built from gap analyses. Re-searched inventory (closure|action_plan|development_plan|remediation|idp|learning_path|career_plan|growth_plan|succession_plan): the only populated near-candidates are engagement_action_plans (6, engagement domain + legacy users link), succession_plans (31, position succession not skill-gap closure), learning_paths (20, catalog not gap-derived) - all semantically wrong domain. No legacy table for skill/competency gap-closure plans exists. Populating needs a human-authored derivation rule turning gap-analysis results into closure plans -> needs-decision derived analytics (C). No real source WITH rows in the closure-plan domain, so tie-breaker ''source WITH rows -> never C'' does not apply.'),
  ('sys_gap_closure_actions', 'C', 'NEEDS_DECISION', NULL, NULL, NULL, '[VERIFIED] Action items within closure plans (kind TRAINING_ASSIGNMENT/CERTIFICATION_REQUIRED/MANAGER_INTERVENTION/PEER_COACHING/ON_THE_JOB_EXPOSURE/MENTORING, status PROPOSED/IN_PROGRESS/COMPLETED/CANCELLED, due_date, payload) derived from learning gaps. Re-searched inventory: no legacy table with rows for per-gap closure actions exists (only wrong-domain engagement_action_plans|6, succession_plans|31, learning_paths|20). Bucket B requires a legacy source WITH rows whose FK fails to resolve; the precondition ''legacy source WITH rows'' is absent, so B does not apply. Derived analytics with no 1:1 source, and the mandatory parent (sys_learning_gaps) is unpopulated (0 rows) -> populating requires a human-authored derivation rule AND prior population of learning gaps. Conservative choice C.'),
  ('sys_bonus_pools', 'A', 'IMPORT', 'public.bonus_plans', 14, 'other:tenant_id Wave-2 reconciliation — 8/14 source rows (SmartFood=5, EcoNova=3) have legacy tenant_id with NO crosswalk in brownfield.tenant_id_mappings', '[sign-off: import RTL subset 6/14; out-of-scope SmartFood/EcoNova rows skip] [CORRECTED A->B: NOT-NULL tenant FK does not resolve for all source rows] sys_bonus_pools is a budget-envelope container and legacy public.bonus_plans (14 rows, re-confirmed) maps ~1:1 on defining columns (total_budget->total_eur, period_start/end, status). HOWEVER the proposed A relied on the tenant FK resolving from sys.* already populated — it does NOT for 8 of 14 rows. The tie-breaker is explicit: ''Source exists AND EVERY (NOT-NULL) FK resolves -> A (not B)''. Here the NOT-NULL bonus_pool_tenant_id resolves for only the 2 RTL/Heuresys legacy tenants (6 rows); the SmartFood + EcoNova legacy tenants (8 rows) have no canonical tenancy and no crosswalk entry. This is a genuine structural wall (the Wave-2 multi-tenant reconciliation deferred per project state), not an optional refinement -> bucket B. On conservatism (A->B->C), B is the correct downgrade: a populated source exists (so never C/D), but a required FK needs a modeling decision.'),
  ('sys_payout_curves', 'C', 'NEEDS_DECISION', NULL, NULL, NULL, '[VERIFIED] sys_payout_curves is a reusable rule/configuration catalog of payout-function shapes (kind in LINEAR/CAPPED/STEPPED/SIGMOID + payload jsonb defining the curve). Re-searched the full legacy inventory (curve|payout|variable_pay|incentive|salary|comp|signal|score) — NO standalone curve/function-definition table exists. The only adjacent legacy data is embedded plan parameters (bonus_plans.performance_multipliers jsonb, merit_cycles.guideline_matrix jsonb), which are plan-level config blobs, not a standalone curve catalog. Populating this needs human-authored curve definitions -> needs-decision derived/authored config. No populated source positively found, so it stays C (never promoted to A/B).'),
  ('sys_variable_pay_calculations', 'C', 'NEEDS_DECISION', NULL, NULL, NULL, '[VERIFIED] sys_variable_pay_calculations is derived analytics: per-user computed variable-pay results whose defining columns are engine outputs (variable_pay_calculation_signal_score numeric(8,4), computed_at engine timestamp, amount_eur). Re-confirmed against the live DDL. The superficially closest legacy table, public.bonus_allocations (244 rows, re-counted), is an allocation ledger (target_amount/actual_amount/performance_multiplier/status pending..paid) with NO signal_score and NO computed-at engine semantics -> columns do NOT map ~1:1. No scored variable-pay calculation table exists in the inventory (the *_scores tables found are talent/risk, not variable pay). Populating requires a human-authored signal/aggregation derivation rule -> needs-decision derived analytics, stays C.'),
  ('sys_compensation_recommendations', 'C', 'NEEDS_DECISION', NULL, NULL, NULL, '[VERIFIED] sys_compensation_recommendations is a recommendation-ENGINE output: defining columns are compensation_recommendation_signal with analytics-gate values (PROPOSED/APPROVED/SUPPRESSED_BY_GATE/ADJUSTED/REJECTED — live CHECK confirmed), computed_at engine timestamp, and a narrative. Legacy public.merit_recommendations (208 rows, re-counted) is semantically adjacent (recommended_increase_amount, new_salary, justification, status) but its status enum (pending/submitted/manager_approved/hr_approved/final_approved/rejected — live CHECK confirmed) is a WORKFLOW-APPROVAL ladder that does NOT map 1:1 to the engine-signal enum; it has no SUPPRESSED_BY_GATE concept and no computed_at engine timestamp. The gate/suppression + computed-signal model is derived analytics requiring a human-authored derivation/gate rule, not a deterministic 1:1 import. The 1:1-column condition for A fails on the defining (signal/gate/computed) columns -> conservative C holds (A->B->C; not B because the blocker is the derivation semantics, not a single resolvable FK).'),
  ('sys_organization_hierarchies', 'D', 'NO_SOURCE', NULL, NULL, NULL, '[VERIFIED] Closure table (ancestor/descendant/depth) — a derived structural artifact, NOT a 1:1 legacy table. Re-confirmed: target empty (count=0). Re-ran legacy search for closure/ancestor/descendant/hierarchy candidates across all public.* tables — ZERO org hierarchy/closure tables exist (the only ''_history''-pattern matches are employee_skill_history / salary_history / recruiting_candidate_history, all unrelated to org structure). The closure is the deterministic transitive closure of the adjacency-list parent pointer that ALREADY lives in legacy public.org_units.parent_id (verified 70/76 rows non-null) and is mapped to sys.sys_organization_units (self-FK organization_unit_parent_id). It is mechanically computable via a recursive CTE from sys.* data already loaded — app/engine-generated, no external legacy source, no human-authored aggregation rule (so not C, which needs a derivation DECISION; the closure is a mechanical derivation with one correct answer). Tie-breaker: derived structure with NO populated legacy source positively found -> D.'),
  ('sys_organization_unit_history', 'D', 'NO_SOURCE', NULL, NULL, NULL, '[VERIFIED] Audit/change-log table: organization_unit_history_change_type CHECK in {CREATED,RENAMED,MOVED,MERGED,SPLIT,DEACTIVATED,REACTIVATED}, jsonb old_value/new_value default ''{}'', effective_at default now(), actor_user_id, notes. Pattern ''*_history'' -> D unless a POPULATED legacy source is positively found. Re-confirmed: NO legacy org-unit change-log/history table exists. Exhaustive legacy ''_history'' search returned ONLY employee_skill_history / salary_history / recruiting_candidate_history (person/comp-centric, NOT org units). It is an app-generated audit trail materialized at runtime as org units are mutated through the API, not imported from legacy. Bucket D (*_history, app-generated, no source) confirmed.'),
  ('sys_branches', 'B', 'NEEDS_DECISION', 'public.locations', 34, 'other:location_to_org_unit_bridge', '[VERIFIED] A real populated legacy source exists (public.locations, verified count=34; 10 of type ''branch'', plus headquarters=8/office=8/factory=4/warehouse=2/NULL=2) whose columns (code,name,address,city,province,postal_code,country) map ~1:1 to sys_branches address fields — so NEVER C/D (real source WITH rows). However sys_branches.branch_organization_unit_id is NOT NULL AND UNIQUE, demanding a 1:1 location<->org_unit pairing. Re-verified the cardinality of the only candidate link: legacy public.org_units.default_location_id -> locations is strongly MANY-org-to-ONE-location (76 org_units, only 47 carry a default_location_id, pointing to just 13 DISTINCT locations; individual locations are shared by 3, 4, 7 and 15 org_units). This is the INVERSE cardinality of what the UNIQUE FK requires, and legacy locations has NO FK back to org_units. No deterministic rule maps each location to a single owning org_unit, so the required UNIQUE NOT-NULL FK cannot resolve without a human-authored bridge decision. -> Structural wall (B) confirmed.'),
  ('sys_reward_gates', 'D', 'NO_SOURCE', NULL, NULL, NULL, '[VERIFIED] v5-native reward-blueprint governance/config: a gate INSTANCE keyed by period_start/end + catalog (+optional user/position) with jsonb payload, fed by sys_reward_gate_catalog (7 config rows). No legacy public table models ''reward gates'' (exact name scan reward|gate => only employee_permission_overrides/permission_overrides, RBAC false friends). Inspected bonus_plans(14): it is the compensation/payout domain (bonus_type annual/quarterly/spot, total_budget, payout_date, calculation_method) = real bonus money to employees, NOT a period+catalog gate instance, no column maps to catalog_id. merit_cycles(53) = salary-increase guideline cycles, also compensation. No brownfield table_mappings row, no source_tables named reward/gate. App/engine-generated config with no positively-found populated legacy source -> conservative D.'),
  ('sys_reward_gate_results', 'C', 'NEEDS_DECISION', NULL, NULL, NULL, '[VERIFIED] Derived analytics: evaluation outputs of reward gates -> result_status CHECK(PASSED/WARNING/BLOCKED/ESCALATED/OVERRIDDEN_WITH_REASON), result_score numeric(8,4), evaluator_user_id, override_reason text + payload jsonb. This is a per-gate scoring/assessment result with no 1:1 legacy source (no reward/gate legacy table; bonus_allocations/merit_recommendations are payout amounts, not gate-evaluation verdicts). Populating it requires a human-authored gate-evaluation/derivation rule applied over the (also unpopulated) gates. Classic scores/results/assessments pattern -> C (analytics with a derivation rule), not D scaffold.'),
  ('sys_objective_reward_rules', 'C', 'NEEDS_DECISION', NULL, NULL, NULL, '[VERIFIED] Derivation-rule table linking objectives to rewards: tenant + code(128) + name(255) + jsonb payload (unique on tenant+code) defining how objective attainment maps to reward outcomes. No 1:1 legacy source: legacy has the objective side (goals=1067, okrs=20, goal_templates=40) and the reward/comp side (bonus_plans=14, merit_cycles=53) but NO table encoding the objective->reward derivation rules; legacy exact scan ~* objective => 0 tables. Populating it needs a human-authored derivation/aggregation rule -> needs-decision derived analytics -> C.'),
  ('sys_blueprint_activations', 'D', 'NO_SOURCE', NULL, NULL, NULL, '[VERIFIED] *_activations tail-pattern: tenant-scoped lifecycle record activating a blueprint VARIANT (status CHECK PROPOSED/ACTIVE/SUSPENDED/RETIRED, effective_from/to, one-active-per-tenant partial unique index, set_updated_at trigger). App-generated runtime governance artifact created when a tenant activates a variant. Inspected legacy blueprint_runs(7) \d: it is an industry-profile org-design GENERATOR run (run_mode greenfield/overlay, template_id->blueprint_templates, produces blueprint_results=484 like org_unit_suggestion/skill_gap) — semantically unrelated to reward-blueprint variant activation lifecycle, and there is NO legacy blueprint_variants table at all. False friend confirmed. Tie-breaker: *_activations -> D unless a POPULATED legacy source positively found; none found.'),
  ('sys_blueprint_overrides', 'D', 'NO_SOURCE', NULL, NULL, NULL, '[VERIFIED] *_overrides tail-pattern: per-process inclusion override (CHECK IN/PARTIAL/OUT) on a blueprint activation, with rationale text + metadata jsonb + set_updated_at trigger -> human/app-generated configuration delta on top of an activation. The only brownfield table_mappings rows present are 4 REFERENCE_ONLY entries from semantically unrelated sources (benchmark_configs, benchmark_reports, holidays, tenant_industry_classifications) -> NOT a real 1:1 import source. The 2 legacy *_override tables (employee_permission_overrides, permission_overrides) are RBAC permission overrides, false friends. Tie-breaker: *_overrides -> D unless a POPULATED legacy import source positively found; none (REFERENCE_ONLY != import source).'),
  ('sys_auth_sessions', 'D', 'NO_SOURCE', NULL, NULL, NULL, '[sign-off: strip session artifact; runtime auth] [VERIFIED] Runtime auth-session table (inet IP, user_agent, expires_at NOT NULL, revoked_at) generated by the API at login. The only name-matching legacy candidate public.session has count(*)=0 (re-verified on VM). Inventory search for *session* yields only domain sessions (calibration_sessions=86, mentorship_sessions=355, org_chart_generation_sessions=3, analysis_sessions=2, rag_sessions=30, preboarding_sessions=30) — none is an auth/login session. App-generated runtime artifact per the D criteria (sessions) with no populated source -> D.'),
  ('sys_inbox_notifications', 'D', 'EXCLUDE', 'notifications', 238, 'other: notification_type + resource_type CHECK-enum remap — legacy free-form type varchar not 1:1, and legacy has NO resource_type/resource_id columns to fill the constrained target columns', '[sign-off: EXCLUDE — runtime notifications, not imported] [VERIFIED] A populated employee-bridged legacy source (238 rows, user_id_employee_id 238/238 non-null, 126 rows importable) is positively confirmed, so NOT D despite ''notifications'' being on the D scaffold list. But the target enforces strict CHECK enums absent from the legacy data: notification_type IN (TRAINING_DEADLINE, ASSESSMENT_REQUEST, MANAGER_FEEDBACK_READY, CAREER_TARGET_STATUS, GAP_CLOSURE_DUE, SYSTEM) and the (nullable) notification_resource_type IN (POSITION, LEARNING_MODULE, ASSESSMENT, CAREER_TARGET, KPI, SKILL). Legacy type values (approval_needed|56, review_pending|42, system_update|38, course_assigned|35, goal_reminder|34, feedback_received|33) map to NONE of the 6 target codes 1:1, and the legacy DDL has NO resource_type/resource_id column at all. A human-authored categorical translation rule is required — a modeling decision, not a deterministic import (A) and not derived analytics (C). FK resolves but the categorical CHECK-enum wall blocks deterministic import -> B.'),
  ('sys_user_preferences', 'D', 'NO_SOURCE', NULL, NULL, NULL, '[VERIFIED] (evidence corrected vs stage-1) Target columns are user_preference_theme (dark/light CHECK, default ''dark'') and user_preference_palette (balanced/cool-ocean/warm-sunset/brand-mono CHECK, default ''balanced'') — UI/UX preferences app-generated by the P1 milestone (locked decision 3c). Stage-1 claimed ''no legacy table carries theme/palette'' — that is FALSE: an information_schema column scan found legacy users.theme_preference (varchar 8) and users.palette_preference_id (varchar 32). HOWEVER these refute to D for two compounding reasons: (1) they are essentially unpopulated — only 1/274 users has a non-null theme_preference (value ''dark'') and 1/274 a non-null palette_preference_id (273 NULL); a single stray value is not a populated source. (2) They sit on legacy `users` (the auth shell / FALSE FRIEND), and sys_user_preferences is a sys_user_* person-centric target which under I14/ADR-0024 must NOT be driven by legacy `users`. The notification_preferences table (266 rows) is a different concept (email/in-app toggles + quiet hours, zero theme/palette). dashboard_presets.theme_config(30)/rbp_dashboards.theme_config(11) are dashboard-presentation JSONB, not per-user UI prefs. App-generated UI preference, no doctrine-valid populated source -> D.'),
  ('sys_user_documents', 'A', 'IMPORT', 'employee_documents', 1089, NULL, '[VERIFIED] A real populated EMPLOYEE-centric legacy source (1089 rows, 264 distinct employees, 657 importable rows on the RTL subset) maps ~1:1 to the target, and every NOT-NULL/FK column resolves from data already in sys.* (sys_users 161 via the I14/ADR-0024 employees->sys_users crosswalk, sys_tenancies 2). The legacy FK is employee_id->employees_core (employee-centric, correct driver — NOT the false-friend users). The kind CHECK''s OTHER catch-all guarantees no categorical gap: contract->CONTRACT_REFERENCE, cv->CV, certificate->CERTIFICATE, and id_document/id_card/payslip/policy_acknowledgment->OTHER. Documents for employees outside the RTL subset filter out (no FK orphan, no wall). Tie-breaker: source exists AND every FK resolves -> A (not B); populated source -> never D despite ''documents'' on the scaffold list.'),
  ('sys_payroll_handoff_records', 'D', 'NO_SOURCE', NULL, NULL, NULL, '[VERIFIED] (evidence corrected vs stage-1) The target is an integration/runtime engine output recording a transmitted payroll handoff (period_start/end, recipient_system, jsonb payload, handed_off_at, status PENDING/SENT/ACKNOWLEDGED/REJECTED default ''SENT''). Candidate legacy tables: payroll_export_jobs has 1 row whose status is ''validation_failed'' (NOT ''draft'' as stage-1 claimed) — i.e. an export job that failed validation and never reached transmission, NOT a handoff/transmission record; payroll_export_files=0, payroll_export_employees=0, payroll_transmission_log=0 (the table that would model actual transmission events is empty). The generic export_jobs(45) is a different domain (config_id/file_url/expires_at generic data exports, no payroll recipient_system/handoff semantics). No populated source holds real handoff/transmission events; the lone failed export job is not a deterministic 1:1 handoff source. App-generated integration artifact -> D.'),
  ('sys_visualization_styles', 'D', 'NO_SOURCE', NULL, NULL, NULL, '[VERIFIED] sys_visualization_* renderer/app-generated table holding per-graph node-type color/icon style overrides (style_node_type, style_color, style_icon, style_metadata jsonb). No legacy table models graph node styling relationally. The only graph-ish legacy candidates (org_chart_snapshots=3, org_chart_templates=9, tenant_org_charts=4, org_chart_generation_sessions=3) embed all presentation inside JSONB blobs (tree_structure, excalidraw_format, template_structure) under a different org-chart domain model — there is no relational per-node-type style table to map 1:1. Explicitly on the D scaffold list (sys_visualization_*); no populated relational source found -> D.'),
  ('sys_visualization_layouts', 'D', 'NO_SOURCE', NULL, NULL, NULL, '[VERIFIED] sys_visualization_* renderer/app-generated table holding layout-engine descriptors (layout_engine CHECK AUTO/DAGRE/ELK/HIERARCHICAL/TREE/SWIMLANE/TIMELINE/FORCE_DIRECTED/MANUAL, version, is_default, layout_metadata jsonb), produced by the visualization layout engine at render time. The table is currently empty (0 rows) and no legacy table provides graph-layout-engine records — org_chart_* store finished excalidraw JSONB, not an engine/version descriptor. On the D scaffold list; no populated relational source -> D.'),
  ('sys_visualization_node_layouts', 'D', 'NO_SOURCE', NULL, NULL, NULL, '[VERIFIED] sys_visualization_* renderer/app-generated table holding computed/manual x/y/z node coordinates per layout (numeric(10,2) x NOT NULL, y NOT NULL, z, locked). Coordinates are produced by the layout engine or user drag, not stored relationally in any legacy table — legacy org charts keep geometry inside excalidraw_format JSONB. It also depends on sys_visualization_layouts which is itself empty (0 rows), so there is no parent layout to attach positions to. App-generated, no relational source -> D.'),
  ('sys_visualization_exports', 'D', 'NO_SOURCE', NULL, NULL, NULL, '[VERIFIED] sys_visualization_* renderer/app-generated table recording produced graph-export artifacts (export_format CHECK SVG/PDF/PNG/GENERIC_JSON/REACT_FLOW_JSON/MERMAID, payload_uri, generated_at). These are engine outputs created when a user exports a graph. No legacy table holds graph-export records: legacy export_jobs(45) and payroll_export_jobs/files/configurations concern generic data/payroll exports (file_url/config_id/period), a different domain — none produce SVG/MERMAID/REACT_FLOW graph renders. On the D scaffold list; no populated graph-export source -> D.'),
  ('sys_seed_acquisition_runs', 'D', 'NO_SOURCE', NULL, NULL, NULL, '[VERIFIED] Root of an AI-driven seed-acquisition engine. Verified DDL columns prove it: seed_acquisition_run_prompt_template (text), seed_acquisition_run_source_registry_payload (jsonb ''[]'' default), seed_acquisition_run_code (generic), status CHECK RUNNING/COMPLETED/FAILED/CANCELLED. Re-ran count(*)=0 and confirmed brownfield.table_mappings classification=<none>. The two name-collision candidates are positively a DIFFERENT subsystem: crawl_runs (count re-verified=1) is a job-posting crawler (columns postings_found/postings_saved/skills_extracted, FK config_id->crawler_configs, feeds job_postings_raw); enrichment_jobs (count=18) is a field-level LLM enrichment engine that patches an EXISTING target_table/target_record_id/field_name with merge policies + idempotency + llm_cost_eur, not a generic prompt-template/source-registry acquisition run. No legacy table has a prompt_template + source_registry_payload analogue. sys_seed_* prefix + no populated 1:1 source -> D per tie-breaker.'),
  ('sys_seed_candidate_records', 'D', 'NO_SOURCE', NULL, NULL, NULL, '[VERIFIED] Generic AI-acquisition candidate staging row produced by the engine. Verified DDL: seed_candidate_record_domain is free varchar, seed_candidate_record_payload is generic jsonb, seed_candidate_record_natural_key engine-assigned, validation_status CHECK PENDING/PASSED/FAILED/WARNING/APPROVED/REJECTED/APPLIED. Re-ran count(*)=0, no brownfield mapping. Legacy collisions positively ruled out at schema level: public.candidates (count re-verified=100, NOT 96 as the stage-1 evidence string stated - the 96 was likely recruiting_candidates; bucket unaffected) is an ATS recruiting person table (first_name/last_name/email/resume_url/linkedin_url) - different domain; public.enrichment_candidates (count=38) is field-level LLM enrichment proposals (entity_type/field_name/candidate_value/confidence/fact_hash, FK job_id->enrichment_jobs) - single-field patches of existing records, not whole-record seed candidates. Neither maps 1:1 to this generic engine staging table; depends on an empty bucket-D parent run. sys_seed_* + no populated 1:1 source -> D.'),
  ('sys_seed_approval_decisions', 'D', 'NO_SOURCE', NULL, NULL, NULL, '[VERIFIED] Human approval-decision audit log of the seed engine (status APPROVED/REJECTED/NEEDS_CHANGES, rationale, decided_at). App-generated workflow output keyed entirely on an empty bucket-D candidate table. Re-ran count(*)=0, no brownfield mapping. The only semantic legacy collision, leave_approval_steps (count re-verified=89), is HR leave-workflow approvals - a wholly different domain that does not map to generic seed-candidate approvals; no 1:1 populated legacy source exists. sys_seed_* prefix + approval/decision log semantics + empty bucket-D parent -> D (conservative tie-breaker holds).'),
  ('sys_seed_source_evidence', 'D', 'NO_SOURCE', NULL, NULL, NULL, '[VERIFIED] Web-source provenance evidence (url, content_hash, retrieved_at) captured by the AI seed-acquisition engine per candidate. Pure runtime/engine artifact. Re-ran count(*)=0, no brownfield mapping. Legacy collisions are unrelated and distinct: self_assessment_evidence (count re-verified=237) is competency self-assessment attachments (person/skill domain); enrichment_source_snapshots (count=27 in inventory) belongs to the separate enrichment subsystem (keyed to enrichment_jobs/enrichment_candidates, captures snapshots of crawled sources for field enrichment, not generic seed-candidate web evidence). Neither is a 1:1 source; depends on an empty bucket-D candidate table. sys_seed_* + provenance/runtime artifact -> D.'),
  ('sys_seed_validation_results', 'D', 'NO_SOURCE', NULL, NULL, NULL, '[VERIFIED] Per-rule validation output emitted mechanically by the seed engine during the candidate validation phase (rule_code, status PASSED/FAILED/WARNING/SKIPPED). Although named *_results (superficially derived-analytics-like, which would suggest C), it is deterministically produced by engine validation rules - not a human-authored derivation/aggregation - and it is part of the sys_seed_* engine chain keyed on an empty bucket-D candidate table, so D not C. Re-ran count(*)=0, no brownfield mapping. Inventory grep for seed/validation returned only payroll_validation_rules (11, a payroll rule catalog - rules not results, different domain) and self_assessment/enrichment subsystem tables; no legacy table emits generic seed-rule validation results. sys_seed_* tie-breaker -> D.'),
  ('sys_user_professional_experiences', 'D', 'NO_SOURCE', NULL, NULL, NULL, '[VERIFIED] Records EXTERNAL prior-employer CV work history (employer varchar(255), role_title varchar(255), industry, start/end date, free-text description) — confirmed by re-reading the DDL. I re-ran the exhaustive grep (experien|employment|prior|work_history|previous|cv|resume|career_hist|past_role|tenure|external) over the 588-table inventory: ZERO external-employer-history tables. I also scanned legacy information_schema for any person column matching company_name|employer_name|organization_name|prev_company|former_employer — only job_market_postings / job_postings_raw matched (job-ad sources, not person history). The scattered ''years_experience'' (candidates, employee_skills) are scalar attributes, not structured employment records. The employees_* satellites (core/hr/payroll/pii, 270 each) + employee_contracts describe the CURRENT employer relationship only. No populated legacy source; ESS self-entry satellite filled at app runtime. Target empty (0 rows). ''has source'' requires positive count>0 which is absent -> D.'),
  ('sys_enterprise_typing_profiles', 'C', 'NEEDS_DECISION', NULL, NULL, NULL, '[VERIFIED] Per-tenant enterprise TYPING/assessment profile (DDL re-read: UNIQUE(enterprise_typing_tenant_id), assessed_at timestamp, regulatory_intensity CHECK in {LOW,MEDIUM,HIGH,EXTREME}, employee_count, revenue_eur, country_code + nullable industry/size-band/operating-model FKs). No 1:1 legacy source: I inspected legacy company_profiles (9) and found it is an ATECO/NACE code CATALOG (section/division/group/size codes, auto-populate trigger) — a reference dimension, NOT a per-tenant company profile. Other fragments (industry_profiles=8, tenant_industry_classifications=4, tenant_onboarding_profiles=4, regulatory_frameworks=10) each cover only a slice. The discriminating fields — size_band assignment, operating_model classification, regulatory_intensity rating — have NO legacy column and require a human-authored derivation/aggregation rule that ''types'' each tenant (analytics-by-assessment). Derived assessment with no 1:1 source -> C, not A/B.'),
  ('sys_person_evidence_records', 'C', 'NEEDS_DECISION', NULL, NULL, NULL, '[VERIFIED] Polymorphic derived EVIDENCE ledger (DDL re-read: person_evidence_type CHECK across SKILL/LEARNING/KPI/ASSESSMENT/CERTIFICATION/BEHAVIORAL; person_evidence_source CHECK across MANAGER_ASSESSMENT/THREE_SIXTY_ASSESSMENT/CERTIFICATION_VERIFIED/SELF_ASSESSMENT/TRAINING_COMPLETION_REASSESSMENT/EXTERNAL_VALIDATOR/AI_INFERRED; opaque jsonb payload + soft polymorphic resource pointer). I checked the closest-named legacy table self_assessment_evidence (237 rows, employee_id-keyed, evidence_type/title/description/verified) — it is REAL with rows but covers ONLY the SELF_ASSESSMENT source (1 of 7, tied to performance_review_id), i.e. a fragment, not 1:1. The full 6-type x 7-source target is a cross-domain UNION over many heterogeneous facts (employee_skill_assessments=3140, feedback_360=714, employee_certifications=729, employee_training_records=320, self_assessment_evidence=237) plus an AI_INFERRED provenance with no legacy analog. No single populated table is 1:1; materializing requires a human-authored rule deciding which facts become evidence rows, how to classify type/source, and the jsonb shape -> derived analytics -> C.'),
  ('sys_behavioral_assessments', 'C', 'NEEDS_DECISION', NULL, NULL, NULL, '[VERIFIED] Derived behavioral ASSESSMENT (DDL re-read: per-user behavioral_assessment_competency varchar(255), behavioral_assessment_score numeric(5,2) nullable, evidence_payload jsonb, recorded_at). Legacy candidates WITH rows confirmed by exact count: feedback_360=714, competency_review_ratings=465, calibration_discussions=60, calibration_results=50, burnout_assessments=54, competencies=32 (catalog). NONE map 1:1 to a single (competency, score) row: feedback_360 carries an overall rating + free-text + jsonb question_responses (not per-competency numeric); competency_review_ratings splits self_rating vs manager_rating (which to pick / how to collapse is a decision); calibration_* are bands/results not a per-competency numeric(5,2). Collapsing these heterogeneous sources into one normalized score per competency requires a human-authored derivation/aggregation rule (source selection, scale normalization, dedup). Derived score/assessment, no 1:1 source -> C (per criteria, derived scores/assessments go to C even when candidate legacy tables have rows).'),
  ('sys_activity_classification_mappings', 'D', 'NO_SOURCE', NULL, NULL, NULL, '[VERIFIED] Self-referential SKOS-style crosswalk (DDL re-read: pairs two sys_activity_classifications rows, kind CHECK in {EXACT,NARROWER,BROADER,RELATED,APPROXIMATE} + confidence numeric(4,3), UNIQUE(source,target)). DECISIVE finding: sys_activity_classifications is an ATECO/NACE economic-activity taxonomy (scheme dist ATECO=2210, NACE=1066, total 3276) sourced 1:1 from legacy industry_classifications (count 3276 EXACT match; same self-referential parent_code hierarchy, level, classification_system NACE/ATECO). But industry_classifications is the DIMENSION (a parent_code tree), NOT a separate (source_code, target_code, mapping_kind, confidence) crosswalk table — there is NO legacy ATECO<->NACE equivalence crosswalk. The legacy crosswalks that exist (occupation_industry_classifications=4565, onet_esco_mappings=135, skill_taxonomy_extensions=52) are cross-ENTITY (occupation<->industry) or cross-taxonomy OCCUPATION/SKILL alignments, none a within-industry-taxonomy classification<->classification SKOS map. brownfield.table_mappings classifies this target REFERENCE_ONLY. No positively-found populated source -> reference scaffold authored from an alignment rule -> D (tie-breaker: reference scaffold stays D unless a POPULATED legacy source is found; none was).')
ON CONFLICT (reconciliation_registry_table_name) DO UPDATE SET
  reconciliation_registry_bucket = EXCLUDED.reconciliation_registry_bucket,
  reconciliation_registry_declared_status = EXCLUDED.reconciliation_registry_declared_status,
  reconciliation_registry_legacy_source = EXCLUDED.reconciliation_registry_legacy_source,
  reconciliation_registry_legacy_source_rows = EXCLUDED.reconciliation_registry_legacy_source_rows,
  reconciliation_registry_wall = EXCLUDED.reconciliation_registry_wall,
  reconciliation_registry_rationale = EXCLUDED.reconciliation_registry_rationale,
  updated_at = now();

DO $$
DECLARE v_total int; v_a int; v_b int; v_c int; v_d int;
BEGIN
  SELECT count(*), count(*) FILTER (WHERE reconciliation_registry_bucket='A'),
         count(*) FILTER (WHERE reconciliation_registry_bucket='B'),
         count(*) FILTER (WHERE reconciliation_registry_bucket='C'),
         count(*) FILTER (WHERE reconciliation_registry_bucket='D')
    INTO v_total, v_a, v_b, v_c, v_d FROM sys.sys_reconciliation_registry;
  RAISE NOTICE 'registry: % rows (A:% B:% C:% D:%)', v_total, v_a, v_b, v_c, v_d;
  IF v_total <> 65 THEN RAISE EXCEPTION 'registry expected 65 rows, got %', v_total; END IF;
END $$;

COMMIT;
